"""Five small domestic gestures for the reference-house study.

Coordinates refer to the 1354 x 1332 source composition.  Each function creates
one independently editable object; callers choose the furniture/figure order.
"""


def _lines(g, stem, segments, color="#373530", width=0.75, opacity=0.85):
    for i, points in enumerate(segments):
        g.line(f"{stem}-{i}", points, color=color, width=width, opacity=opacity)


